WITH events AS (SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Entered' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='E')) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Reviewed' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='R')) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Cancelled' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='C')) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'LABEV:'||e.labevent_id||':result' event_id,'LAB:'||o.order_id object_id,'Lab Result Available' activity,e.storetime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.storetime IS NOT NULL AND (1=1)) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'LAB:'||order_id||':verified' event_id,'LAB:'||order_id object_id,'Lab Results Verified' activity,results_verified_at timestamp FROM lab_order WHERE results_verified_at IS NOT NULL AND (1=1)) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'LABEV:'||e.labevent_id||':chart' event_id,'LAB:'||o.order_id object_id,'Specimen Collected' activity,e.charttime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (1=1)) WHERE object_id LIKE 'LAB:%' UNION ALL SELECT * FROM (SELECT 'LAB:'||order_id||':received' event_id,'LAB:'||order_id object_id,'Specimen Received' activity,specimen_received_at timestamp FROM lab_order WHERE specimen_received_at IS NOT NULL AND (1=1)) WHERE object_id LIKE 'LAB:%'), orders AS (SELECT 'LAB:'||order_id object_id,hadm_id,subject_id FROM lab_order) SELECT e.event_id,'A:'||o.hadm_id case_id,e.activity,e.timestamp FROM events e JOIN orders o ON o.object_id=e.object_id WHERE o.hadm_id IS NOT NULL ORDER BY case_id,timestamp,event_id;
